// Geo map's elevation and depth bands (ADR-220).
//
// `geoRelief.json` is generated by `scripts/gen-geo-relief.mjs` from NOAA's ETOPO 2022 grid —
// never edit it by hand. It holds one evenodd path per level, in the 720 × 360 grid
// `geoProjection.ts` draws in, and each level is the region at or above it, so the levels nest and
// are painted lowest first. It is its own chunk, fetched only once an operator switches the
// colouring on: the grey map stays the default and costs nothing more.

import { useEffect, useState } from 'react';

/** The sea levels, deepest first, in metres. Must match the generator's `SEA_LEVELS`. */
export const RELIEF_SEA_LEVELS = [-5000, -3000, -1000, -200] as const;
/** The land levels, lowest first, in metres. Must match the generator's `LAND_LEVELS`. */
export const RELIEF_LAND_LEVELS = [200, 500, 1000, 2000, 3000, 4500] as const;

export interface ReliefBand {
  level: number;
  d: string;
}

export interface GeoRelief {
  sea: ReliefBand[];
  land: ReliefBand[];
}

/** One band to draw: its class (which names its colour token) and its path. */
export interface ReliefLayer {
  className: string;
  d: string;
}

/** Sea band `i` (0 = the deepest level) is `geopage-relief-sea-<i+1>`; `geopage-relief-sea-0` is
 *  the water deeper than every level, painted under them all. */
export function seaClass(i: number): string {
  return `geopage-relief-sea-${i + 1}`;
}

/** Land band `i` (0 = 200 m) is `geopage-relief-land-<i+1>`; land below the first level is lowland. */
export function landClass(i: number): string {
  return `geopage-relief-land-${i + 1}`;
}

/** The bands in the order the page paints them, each with its class. */
export function reliefLayers(relief: GeoRelief): { sea: ReliefLayer[]; land: ReliefLayer[] } {
  return {
    sea: relief.sea.map((b, i) => ({ className: seaClass(i), d: b.d })),
    land: relief.land.map((b, i) => ({ className: landClass(i), d: b.d })),
  };
}

/** The legend's land swatches: lowland, then each level with the class that paints above it. */
export const RELIEF_LEGEND: readonly { className: string; level: number }[] = [
  { className: 'geopage-relief-lowland', level: 0 },
  ...RELIEF_LAND_LEVELS.map((level, i) => ({ className: landClass(i), level })),
];

let cached: GeoRelief | null = null;
let pending: Promise<GeoRelief> | null = null;

/** Load the bands once per page load; later callers share the first request. */
export function loadGeoRelief(): Promise<GeoRelief> {
  if (cached) return Promise.resolve(cached);
  pending ??= import('./geoRelief.json').then((m) => {
    cached = m.default as GeoRelief;
    return cached;
  });
  return pending;
}

/**
 * The bands, once loaded, while `on`; `null` otherwise. Nothing is fetched until the first time
 * `on` is true. A chunk that fails to load leaves the map grey rather than broken, and is asked
 * for again the next time the switch is pressed.
 */
export function useGeoRelief(on: boolean): GeoRelief | null {
  const [relief, setRelief] = useState<GeoRelief | null>(cached);
  useEffect(() => {
    if (!on || relief) return;
    let live = true;
    loadGeoRelief()
      .then((r) => {
        if (live) setRelief(r);
      })
      .catch(() => {
        pending = null;
      });
    return () => {
      live = false;
    };
  }, [on, relief]);
  return on ? relief : null;
}
